<template>
  <div class="discount-mapping-table q-mb-xl">
    <div class="row items-center q-mb-sm">
      <div class="text-subtitle2">{{ $t('discount_mapping_overwrites') }}</div>
      <q-space />
      <f-btn
        :label="$t('add_mapping')"
        icon="add"
        @click="showAddDialog = true"
      />
    </div>

    <q-table
      :rows="rows"
      :columns="columns"
      row-key="id"
      flat
      bordered
      dense
      binary-state-sort
      :pagination="{ rowsPerPage: 0 }"
      hide-bottom
    >
      <template v-slot:body-cell-percentage="props">
        <q-td :props="props">
          {{ props.row.percentage !== null && props.row.percentage !== undefined ? `${props.row.percentage}%` : '—' }}
        </q-td>
      </template>
      <template v-slot:body-cell-days="props">
        <q-td :props="props">
          {{ props.row.days !== null && props.row.days !== undefined ? props.row.days : '—' }}
        </q-td>
      </template>
      <template v-slot:body-cell-actions="props">
        <q-td :props="props" class="text-right">
          <q-btn
            flat
            round
            dense
            color="negative"
            icon="delete"
            @click="confirmDelete(props.row)"
          >
            <q-tooltip>{{ $t('delete') }}</q-tooltip>
          </q-btn>
        </q-td>
      </template>
    </q-table>

    <!-- Add Dialog -->
    <q-dialog v-model="showAddDialog" persistent>
      <q-card style="min-width: 350px">
        <q-card-section>
          <div class="text-h6">{{ $t('add_discount_overwrite') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <q-input
            v-model="newEntry.prefix"
            :label="$t('prefix')"
            outlined
            dense
            class="q-mb-md"
            autofocus
          />
          <q-input
            v-model.number="newEntry.percentage"
            :label="$t('percentage')"
            type="number"
            step="0.1"
            outlined
            dense
            class="q-mb-md"
          />
          <q-input
            v-model.number="newEntry.days"
            :label="$t('days')"
            type="number"
            min="0"
            outlined
            dense
          />
        </q-card-section>

        <q-card-actions align="right" class="text-primary">
          <q-btn flat :label="$t('Cancel')" v-close-popup />
          <q-btn flat :label="$t('Add')" @click="addEntry" v-close-popup />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <ConfirmDialog
      v-model="showDeleteDialog"
      @confirm="deleteEntry"
      :message="$t('delete_mapping_confirm')"
      :confirmLabel="$t('delete')"
      :cancelLabel="$t('Cancel')"
      confirmAppearance="negative"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { invoiceCalculationApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';

interface DiscountMapping {
  id: string;
  prefix: string;
  percentage: number | null;
  days: number | null;
}

export default defineComponent({
  name: 'DiscountMappingTable',
  components: {
    ConfirmDialog,
  },
  data() {
    return {
      columns: [
        {
          name: 'prefix',
          label: this.t('prefix'),
          field: 'prefix',
          align: 'left',
          sortable: true,
        },
        {
          name: 'percentage',
          label: this.t('percentage'),
          field: 'percentage',
          align: 'left',
          sortable: true,
        },
        {
          name: 'days',
          label: this.t('days'),
          field: 'days',
          align: 'left',
          sortable: true,
        },
        {
          name: 'actions',
          label: '',
          field: 'actions',
          align: 'right',
        },
      ] as any,
      rows: [] as DiscountMapping[],
      showAddDialog: false,
      showDeleteDialog: false,
      rowPendingDelete: null as DiscountMapping | null,
      newEntry: {
        prefix: '',
        percentage: 0,
        days: null as number | null,
      },
    };
  },
  mounted: function () {
    this.fetchMappings();
  },
  methods: {
    async fetchMappings() {
      try {
        const response =
          await invoiceCalculationApiService.listDiscountMappings();

        if (response && response.success && Array.isArray(response.data)) {
          this.rows = response.data;
        }
      } catch (error) {
        logError('Failed to fetch discount mappings:', error);
      }
    },

    applyRow(row: DiscountMapping) {
      const index = this.rows.findIndex((entry) => entry.id === row.id);
      if (index === -1) {
        this.rows = [...this.rows, row];
        return;
      }
      this.rows[index] = row;
    },

    async addEntry() {
      if (!this.newEntry.prefix) return;

      try {
        const response =
          await invoiceCalculationApiService.upsertDiscountMapping(
            this.newEntry.prefix,
            this.newEntry.percentage || null,
            this.newEntry.days,
          );

        if (response && response.success === false) {
          // Throw so the catch block runs the response through
          // ApiExceptions.getErrorMessage — which translates error_code via i18n.
          throw response;
        }

        if (response?.data?.id) {
          this.applyRow(response.data);
        } else {
          await this.fetchMappings();
        }

        notify.success(this.t('mapping_added_successfully'));
      } catch (error) {
        notify.error(
          ApiExceptions.getErrorMessage(error as any) ||
            this.t('mapping_add_failed'),
        );
      } finally {
        this.newEntry = { prefix: '', percentage: 0, days: null };
      }
    },

    confirmDelete(row: DiscountMapping) {
      this.rowPendingDelete = row;
      this.showDeleteDialog = true;
    },

    async deleteEntry() {
      const row = this.rowPendingDelete;
      if (!row) return;

      try {
        const response =
          await invoiceCalculationApiService.deleteDiscountMapping(row.id);

        if (response && response.success === false) {
          // Throw so the catch block runs the response through
          // ApiExceptions.getErrorMessage — which translates error_code via i18n.
          throw response;
        }

        this.rows = this.rows.filter((entry) => entry.id !== row.id);

        notify.success(this.t('mapping_deleted_successfully'));
      } catch (error) {
        notify.error(
          ApiExceptions.getErrorMessage(error as any) ||
            this.t('mapping_delete_failed'),
        );
      } finally {
        this.rowPendingDelete = null;
      }
    },
  },
  setup() {
    const { t } = useTranslate();

    return { t };
  },
});
</script>