<template>
  <div class="payment-term-mapping-table q-mb-xl">
    <div class="row items-center q-mb-sm">
      <div class="text-subtitle2">{{ $t('payment_term_mapping_overwrites') }}</div>
      <q-space />
      <f-btn
        :label="$t('add_mapping')"
        icon="add"
        @click="showAddDialog = true"
      />
    </div>

    <q-table
      :rows="rows"
      :columns="columns"
      row-key="id"
      flat
      bordered
      dense
      binary-state-sort
      :pagination="{ rowsPerPage: 0 }"
      hide-bottom
    >
      <template v-slot:body-cell-actions="props">
        <q-td :props="props" class="text-right">
          <q-btn
            flat
            round
            dense
            color="negative"
            icon="delete"
            @click="confirmDelete(props.row)"
          >
            <q-tooltip>{{ $t('delete') }}</q-tooltip>
          </q-btn>
        </q-td>
      </template>
    </q-table>

    <!-- Add Dialog -->
    <q-dialog v-model="showAddDialog" persistent>
      <q-card style="min-width: 400px">
        <q-card-section>
          <div class="text-h6">{{ $t('add_payment_term_mapping') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <q-input
            v-model="newEntry.code"
            :label="$t('erp_code')"
            outlined
            dense
            class="q-mb-md"
            autofocus
          />
          <q-select
            v-model="newEntry.term_type"
            :options="termTypeOptions"
            :label="$t('term_type')"
            outlined
            dense
            emit-value
            map-options
            class="q-mb-md"
          />
          <q-input
            v-model.number="newEntry.days"
            :label="$t('days')"
            type="number"
            outlined
            dense
            class="q-mb-md"
          />
          <q-input
            v-model="newEntry.description"
            :label="$t('description')"
            outlined
            dense
          />
        </q-card-section>

        <q-card-actions align="right" class="text-primary">
          <q-btn flat :label="$t('Cancel')" v-close-popup />
          <q-btn flat :label="$t('Add')" @click="addEntry" v-close-popup />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <ConfirmDialog
      v-model="showDeleteDialog"
      @confirm="deleteEntry"
      :message="$t('delete_mapping_confirm')"
      :confirmLabel="$t('delete')"
      :cancelLabel="$t('Cancel')"
      confirmAppearance="negative"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { invoiceCalculationApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';

interface PaymentTermMapping {
  id: string;
  code: string;
  term_type: string;
  days: number;
  description: string | null;
}

const termTypeOptions = [
  { label: 'Net (Standard)', value: 'net' },
  { label: 'Receipt (Immediate)', value: 'receipt' },
  { label: 'DOM (Day of Month)', value: 'dom' },
  { label: 'EOM (End of Month)', value: 'eom' },
];


export default defineComponent({
  name: 'PaymentTermMappingTable',
  components: {
    ConfirmDialog,
  },
  data() {
    return {
      columns: [
        {
          name: 'code',
          label: this.t('code'),
          field: 'code',
          align: 'left',
          sortable: true,
        },
        {
          name: 'term_type',
          label: this.t('term_type'),
          field: 'term_type',
          align: 'left',
          sortable: true,
        },
        {
          name: 'days',
          label: this.t('days'),
          field: 'days',
          align: 'left',
          sortable: true,
        },
        {
          name: 'description',
          label: this.t('description'),
          field: 'description',
          align: 'left',
          sortable: true,
        },
        {
          name: 'actions',
          label: '',
          field: 'actions',
          align: 'right',
        },
      ] as any,
      termTypeOptions,
      rows: [] as PaymentTermMapping[],
      showAddDialog: false,
      showDeleteDialog: false,
      rowPendingDelete: null as PaymentTermMapping | null,
      newEntry: {
        code: '',
        term_type: 'net',
        days: 0,
        description: '',
      },
    };
  },
  mounted: function () {
    this.fetchMappings();
  },
  methods: {
    async fetchMappings() {
      try {
        const response =
          await invoiceCalculationApiService.listPaymentTermMappings();

        if (response && response.success && Array.isArray(response.data)) {
          this.rows = response.data;
        }
      } catch (error) {
        logError('Failed to fetch payment term mappings:', error);
      }
    },

    applyRow(row: PaymentTermMapping) {
      const index = this.rows.findIndex((entry) => entry.id === row.id);
      if (index === -1) {
        this.rows = [...this.rows, row];
        return;
      }
      this.rows[index] = row;
    },

    async addEntry() {
      if (!this.newEntry.code) return;

      try {
        const response =
          await invoiceCalculationApiService.upsertPaymentTermMapping(
            this.newEntry.code,
            this.newEntry.term_type,
            this.newEntry.days,
            this.newEntry.description || undefined,
          );

        if (response && response.success === false) {
          // Throw so the catch block runs the response through
          // ApiExceptions.getErrorMessage — which translates error_code via i18n
          throw response;
        }

        if (response?.data?.id) {
          this.applyRow(response.data);
        } else {
          await this.fetchMappings();
        }

        notify.success(this.t('mapping_added_successfully'));
      } catch (error) {
        notify.error(
          ApiExceptions.getErrorMessage(error as any) ||
            this.t('mapping_add_failed'),
        );
      } finally {
        this.newEntry = { code: '', term_type: 'net', days: 0, description: '' };
      }
    },

    confirmDelete(row: PaymentTermMapping) {
      this.rowPendingDelete = row;
      this.showDeleteDialog = true;
    },

    async deleteEntry() {
      const row = this.rowPendingDelete;
      if (!row) return;

      try {
        const response =
          await invoiceCalculationApiService.deletePaymentTermMapping(row.id);

        if (response && response.success === false) {
          // Throw so the catch block runs the response through
          // ApiExceptions.getErrorMessage — which translates error_code via i18n.
          throw response;
        }

        this.rows = this.rows.filter((entry) => entry.id !== row.id);

        notify.success(this.t('mapping_deleted_successfully'));
      } catch (error) {
        notify.error(
          ApiExceptions.getErrorMessage(error as any) ||
            this.t('mapping_delete_failed'),
        );
      } finally {
        this.rowPendingDelete = null;
      }
    },
  },
  setup() {
    const { t } = useTranslate();

    return { t };
  },
});
</script>