<template>
  <!-- DK-10: compact single-row toggle. Parent accordion already
       provides the "Due Date Calculation" header, so we don't
       duplicate it here — just one tight row with label + toggle and
       a short hint underneath. Minimal padding, no card wrapper. -->
  <div class="calc-fields-toggle row items-start q-py-sm q-px-none no-wrap">
    <div class="col">
      <div class="text-subtitle2 text-weight-medium q-mb-xs">
        {{ $t('calculated_fields_enable_label') }}
      </div>
      <div class="text-caption text-grey-7 calc-fields-toggle__hint">
        {{ $t('calculated_fields_enable_hint') }}
      </div>
    </div>
    <div class="col-auto q-ml-md flex items-center" style="min-height: 24px;">
      <q-toggle
        v-model="enabled"
        :disable="saving"
        color="primary"
        @update:model-value="onToggle"
        data-test="calculated-fields-enable-toggle"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { notify } from 'src/components/notifications/notify';
import { useSettingStore } from 'src/store/main';
import { useDocTypeFieldsStore } from 'src/store/Settings/doc_type_fields.store';
import { preferencesService } from 'src/services/preferences/preferencesService';
import { toBoolPreference } from 'src/utils/preferenceBool';

const PREF_KEY = 'INVOICE_CALCULATION_FIELDS_ENABLED';

const settingsStore = useSettingStore();
const { org_based_settings } = storeToRefs(settingsStore);

const enabled = ref(false);
const saving = ref(false);
let lastPersisted = false;

const loadPreference = async () => {
  try {
    const value = await preferencesService.getOrgPreference(PREF_KEY);
    enabled.value = toBoolPreference(value);
    lastPersisted = enabled.value;
  } catch (error) {
    console.error('Failed to load calculated_fields preference:', error);
    enabled.value = false;
    lastPersisted = false;
  }
};

onMounted(() => {
  loadPreference();
});

const onToggle = async (newValue: boolean) => {
  if (saving.value) return;
  saving.value = true;
  try {
    // Real boolean, not a string literal: lets setOrgPreference route this
    // through the typed SDK endpoint (INVOICE_CALCULATION_FIELDS_ENABLED is
    // in BOOLEAN_PREFERENCE_KEYS) instead of always falling back to the
    // untyped string endpoint.
    const result = await preferencesService.setOrgPreference(PREF_KEY, newValue);
    if (!result?.success) {
      throw new Error('preferencesService.setOrgPreference returned non-success');
    }
    org_based_settings.value[PREF_KEY] = newValue ? 'true' : 'false';
    lastPersisted = newValue;
    // Invalidate cached doc-type fields so the next dashboard column-
    // customizer / Quick Search / email-template variable picker
    // re-fetches with the new gate state. Without this, calc fields
    // stay visible after toggle OFF until a hard page refresh.
    const docTypeFieldsStore = useDocTypeFieldsStore();
    docTypeFieldsStore.fields_doc_type_list = {};
    docTypeFieldsStore.docTypesFieldsGroup = {};
    notify.success(i18n.t('saved_successfully'));
  } catch (error) {
    console.error('Failed to save calculated_fields preference:', error);
    enabled.value = lastPersisted;
    notify.error(i18n.t('save_failed_please_retry'));
  } finally {
    saving.value = false;
  }
};

defineExpose({ enabled, onToggle, loadPreference });
</script>

<style lang="scss" scoped>
.calc-fields-toggle {
  max-width: 900px;
  &__hint {
    line-height: 1.4;
    max-width: 640px;
  }
}
</style>
